CREATE TABLE stud (
  nr_matricol CHAR(6) CONSTRAINT pk_stud PRIMARY KEY,
  email       VARCHAR2(30) CONSTRAINT uq_stud_email UNIQUE,
  an          NUMBER(1) CONSTRAINT ck_stud_an CHECK (an BETWEEN 1 AND 3)
);
CREATE TABLE nota_stud (
  nr_matricol CHAR(6) CONSTRAINT fk_nota_stud REFERENCES stud(nr_matricol),
  valoare     NUMBER(2) CONSTRAINT ck_nota CHECK (valoare BETWEEN 1 AND 10)
);

